class Solution:
    def minElements(self, nums: List[int], limit: int, goal: int) -> int:
        diff = abs(goal - sum(nums))
        steps = 0
        while diff > 0:
            diff -= limit
            steps += 1
        return steps

c.cpp:
class Solution {
public:
    int minElements(vector<int>& nums, int limit, int goal) {
        long long sum = 0;
        for (int x : nums) sum += x;
        long long diff = llabs((long long)goal - sum);
        long long steps = 0;
        while (diff > 0) {
            diff -= limit;
            steps++;
        }
        return (int)steps;
    }
};

